// 由 build/build.mjs 自动生成，请勿手动修改
export const CSS = ":root {\r\n  --brand: #1677ff;\r\n  --brand-strong: #0958d9;\r\n  --call: #16a34a;\r\n  --call-strong: #15803d;\r\n  --ink: #1a1a1a;\r\n  --ink-2: #5c6470;\r\n  --ink-3: #8b94a3;\r\n  --bg: #f2f4f7;\r\n  --surface: #ffffff;\r\n  --line: #e6e9ef;\r\n  --danger: #d92d20;\r\n  --radius: 16px;\r\n  --shadow: 0 1px 2px rgba(16, 24, 40, .06), 0 8px 24px rgba(16, 24, 40, .06);\r\n  --safe-b: env(safe-area-inset-bottom, 0px);\r\n}\r\n\r\n@media (prefers-color-scheme: dark) {\r\n  :root {\r\n    --ink: #f2f4f7;\r\n    --ink-2: #a7b0be;\r\n    --ink-3: #7b8494;\r\n    --bg: #101319;\r\n    --surface: #181d25;\r\n    --line: #262c36;\r\n    --shadow: 0 1px 2px rgba(0, 0, 0, .4), 0 8px 24px rgba(0, 0, 0, .3);\r\n  }\r\n}\r\n\r\n* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\r\n\r\nhtml, body { height: 100%; }\r\n\r\nbody {\r\n  margin: 0;\r\n  background: var(--bg);\r\n  color: var(--ink);\r\n  font-family: system-ui, -apple-system, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\r\n  -webkit-font-smoothing: antialiased;\r\n  text-rendering: optimizeLegibility;\r\n}\r\n\r\nbutton { font: inherit; color: inherit; }\r\n\r\n/* ============================ 首页 ============================ */\r\n\r\n.home-body {\r\n  background:\r\n    radial-gradient(1100px 460px at 50% -180px, rgba(22, 119, 255, .14), transparent 70%),\r\n    var(--bg);\r\n}\r\n\r\n.home {\r\n  max-width: 780px;\r\n  margin: 0 auto;\r\n  min-height: 100vh;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  padding: 64px 22px;\r\n  box-sizing: border-box;\r\n}\r\n\r\n.home-hero { text-align: center; }\r\n\r\n.home-badge {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  height: 28px;\r\n  padding: 0 14px;\r\n  border-radius: 999px;\r\n  background: rgba(22, 119, 255, .12);\r\n  color: var(--brand-strong);\r\n  font-size: 12.5px;\r\n  font-weight: 600;\r\n  letter-spacing: .04em;\r\n}\r\n\r\n@media (prefers-color-scheme: dark) {\r\n  .home-badge { color: #6ba6ff; }\r\n}\r\n\r\n.home-hero h1 {\r\n  margin: 20px 0 0;\r\n  font-size: 34px;\r\n  line-height: 1.35;\r\n  font-weight: 800;\r\n  letter-spacing: -.02em;\r\n}\r\n\r\n.home-cta {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 10px;\r\n  justify-content: center;\r\n  margin-top: 32px;\r\n}\r\n\r\n.home-btn-primary { height: 50px; padding: 0 30px; font-size: 15.5px; border-radius: 999px; }\r\n.home-btn-ghost { height: 50px; padding: 0 24px; font-size: 15px; border-radius: 999px; }\r\n\r\n@media (max-width: 620px) {\r\n  .home { padding: 44px 18px; }\r\n  .home-hero h1 { font-size: 26px; }\r\n  .home-cta { flex-direction: column; }\r\n  .home-cta .btn { width: 100%; }\r\n}\r\n\r\n/* ============================ 扫码页（岛屿风格） ============================ */\r\n\r\n/*\r\n * 设计语言参考 animal-island-ui：暖羊皮纸底色、棕色文字（不用纯黑）、\r\n * 薄荷青主色、大圆角药丸控件、仅底部一层的 3D 按键投影。\r\n * 所有令牌都挂在 .park-body 上，后台页面不受影响。\r\n */\r\n.park-body {\r\n  --island-bg: #7dc395;\n  /* 绿色底纹上直接排字的深棕（对比度足够，不用纯黑） */\n  --island-ink-on-bg: #4a3a28;\n  --island-text-on-bg: #4f3f2c;\r\n  --island-content: rgb(247, 243, 223);\r\n  --island-input: #fffbe7;\r\n  --island-ink: #794f27;\r\n  --island-text: #725d42;\r\n  --island-muted: #8a7b66;\r\n  --island-line: #c4b89e;\r\n  --island-line-soft: #d4c9b4;\r\n  --island-primary: #19c8b9;\r\n  --island-primary-hover: #3dd4c6;\r\n  --island-primary-active: #11a89b;\r\n  --island-primary-bg: #e6f9f6;\r\n  --island-focus: #ffcc00;\r\n  --island-shadow: #bdaea0;\r\n  --island-ease: cubic-bezier(.4, 0, .2, 1);\r\n\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  min-height: 100%;\r\n  background-color: var(--island-bg);\r\n  background-image: url(/assets/bg.webp);\r\n  background-repeat: repeat;\r\n  background-size: auto;\r\n  animation: island-bg-scroll 80s linear infinite;\r\n  color: var(--island-text);\r\n  font-family: Nunito, \"Noto Sans SC\", -apple-system, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\r\n  font-weight: 500;\r\n  -webkit-font-smoothing: antialiased;\r\n}\r\n\r\n/* 呼应动物岛风格的缓慢平铺背景滚动 */\r\n@keyframes island-bg-scroll {\r\n  from { background-position: 100% 0%; }\r\n  to { background-position: 0% 100%; }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n  .park-body { animation: none; }\r\n}\r\n\r\n.park {\r\n  width: 100%;\r\n  max-width: 460px;\r\n  padding: 24px 18px 28px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 16px;\r\n  flex: 1 0 auto;\r\n}\r\n\r\n/* 页脚海浪装饰：水平无缝平铺，贴在页面最底部 */\r\n.park-sea {\r\n  width: 100%;\r\n  height: 80px;\r\n  flex: 0 0 auto;\r\n  margin-top: auto;\r\n  background: url(/assets/sea.svg) left bottom / auto 100% repeat-x;\r\n}\r\n\r\n@media (max-width: 560px) {\r\n  .park-sea { height: 62px; }\r\n}\r\n\r\n/* 示例页顶部提示条 */\r\n.park-body .demo-tip {\r\n  padding: 9px 16px;\r\n  border: 2px dashed #e0c56a;\r\n  border-radius: 14px;\r\n  background: #fdf7e2;\r\n  color: #8a6a12;\r\n  font-size: 12.5px;\r\n  line-height: 1.55;\r\n  font-weight: 500;\r\n  text-align: center;\r\n}\r\n\r\n.park-hero {\r\n  position: relative;\r\n  text-align: center;\r\n  padding: 12px 6px 0;\r\n}\r\n\r\n/* 燕尾绶带式标签 */\r\n.park-badge {\r\n  display: inline-block;\r\n  padding: 7px 24px;\r\n  background: var(--island-primary);\r\n  color: #fff;\r\n  font-size: 12.5px;\r\n  font-weight: 700;\r\n  letter-spacing: .1em;\r\n  clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 50%, 100% 100%, 0 100%, 10px 50%);\r\n}\r\n\r\n.park-hero h1 {\r\n  margin: 16px 0 8px;\r\n  font-size: 23px;\r\n  line-height: 1.4;\r\n  font-weight: 800;\r\n  letter-spacing: .01em;\r\n  color: var(--island-ink-on-bg);\r\n}\r\n\r\n.park-hero p {\r\n  margin: 0;\r\n  color: var(--island-text-on-bg);\r\n  font-size: 13.5px;\r\n  line-height: 1.65;\r\n}\r\n\r\n.park-cars {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n}\r\n\r\n/* 手风琴：多车时一次只展开一辆 */\r\n.acc-item {\r\n  border: 2px solid var(--island-line);\r\n  border-radius: 20px;\r\n  background: var(--island-content);\r\n  overflow: hidden;\r\n  transition: border-color .3s var(--island-ease), background-color .3s var(--island-ease);\r\n}\r\n\r\n.acc-item.is-open {\r\n  border-color: var(--island-primary);\r\n  background: var(--island-content);\r\n}\r\n\r\n.acc-head {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 12px;\r\n  width: 100%;\r\n  padding: 14px 16px;\r\n  border: 0;\r\n  background: transparent;\r\n  text-align: left;\r\n  cursor: pointer;\r\n}\r\n\r\n.acc-head-static { cursor: default; }\r\n\r\n/* 车牌做成一块内嵌的象牙色小牌 */\r\n.acc-plate {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  padding: 5px 14px;\r\n  border: 2px solid var(--island-line-soft);\r\n  border-radius: 12px;\r\n  background: var(--island-input);\r\n  color: var(--island-ink);\r\n  font-size: 17px;\r\n  font-weight: 800;\r\n  letter-spacing: .07em;\r\n  font-variant-numeric: tabular-nums;\r\n  white-space: nowrap;\r\n}\r\n\r\n.acc-item.is-open .acc-plate { border-color: var(--island-primary); }\r\n\r\n.acc-chevron {\r\n  width: 18px;\r\n  height: 18px;\r\n  flex: 0 0 18px;\r\n  color: var(--island-muted);\r\n  transition: transform .3s var(--island-ease), color .3s var(--island-ease);\r\n}\r\n\r\n.acc-item.is-open .acc-chevron {\r\n  transform: rotate(180deg);\r\n  color: var(--island-primary);\r\n}\r\n\r\n.acc-panel {\r\n  display: grid;\r\n  grid-template-rows: 0fr;\r\n  transition: grid-template-rows .3s var(--island-ease);\r\n}\r\n\r\n.acc-item.is-open .acc-panel { grid-template-rows: 1fr; }\r\n\r\n.acc-panel-inner {\r\n  overflow: hidden;\r\n  padding: 0 16px;\r\n}\r\n\r\n.acc-item.is-open .acc-panel-inner { padding-bottom: 16px; }\r\n\r\n/* 单车时不需要折叠动效，直接常开 */\r\n.park-cars.is-single .acc-panel { grid-template-rows: 1fr; }\r\n.park-cars.is-single .acc-panel-inner {\r\n  display: flex;\r\n  justify-content: center;\r\n  padding: 6px 16px 26px;\r\n}\r\n\r\n/* 单车页（含一车一码）：呼叫按钮做成大圆形，拇指热区更大更好按 */\r\n.park-cars.is-single .call-btn {\r\n  flex-direction: column;\r\n  gap: 10px;\r\n  width: 176px;\r\n  height: 176px;\r\n  padding: 0;\r\n  border-radius: 50%;\r\n  font-size: 19px;\r\n  letter-spacing: .06em;\r\n  box-shadow: 0 8px 0 0 var(--island-shadow);\r\n}\r\n\r\n.park-cars.is-single .call-btn svg { width: 46px; height: 46px; flex: 0 0 46px; }\n\n/* 圆内文字最多两行，避免「正在获取号码…」把圆撑变形 */\n.park-cars.is-single .call-btn .call-label {\n  max-width: 128px;\n  line-height: 1.3;\n  text-align: center;\n}\r\n\r\n.park-cars.is-single .call-btn:hover {\r\n  box-shadow: 0 10px 0 0 var(--island-shadow);\r\n  transform: translateY(-2px);\r\n}\r\n\r\n.park-cars.is-single .call-btn:active {\r\n  box-shadow: 0 2px 0 0 var(--island-shadow);\r\n  transform: translateY(6px);\r\n}\r\n\r\n.park-cars.is-single .call-btn[disabled] {\r\n  box-shadow: 0 5px 0 0 var(--island-line-soft);\r\n  transform: none;\r\n}\r\n\r\n@media (max-width: 360px) {\r\n  .park-cars.is-single .call-btn { width: 156px; height: 156px; font-size: 17px; }\r\n  .park-cars.is-single .call-btn svg { width: 40px; height: 40px; flex-basis: 40px; }\r\n}\r\n\r\n.park-actions { margin-top: auto; padding-top: 6px; }\r\n\r\n/* 主行动按钮：药丸形 + 底部单层 3D 投影，按下时整体下沉 */\r\n.call-btn {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 10px;\r\n  width: 100%;\r\n  height: 56px;\r\n  padding: 0 20px;\r\n  border: 0;\r\n  border-radius: 50px;\r\n  background: var(--island-primary);\r\n  color: #fff;\r\n  font-size: 17px;\r\n  font-weight: 700;\r\n  letter-spacing: .04em;\r\n  box-shadow: 0 5px 0 0 var(--island-shadow);\r\n  cursor: pointer;\r\n  transition: background-color .25s var(--island-ease), box-shadow .15s var(--island-ease),\r\n    transform .15s var(--island-ease);\r\n}\r\n\r\n.call-btn:hover {\r\n  background: var(--island-primary-hover);\r\n  box-shadow: 0 6px 0 0 var(--island-shadow);\r\n  transform: translateY(-1px);\r\n}\r\n\r\n.call-btn:active {\r\n  background: var(--island-primary-active);\r\n  box-shadow: 0 1px 0 0 var(--island-shadow);\r\n  transform: translateY(3px);\r\n}\r\n\r\n.call-btn[disabled] {\r\n  background: #f0ece2;\r\n  color: #c4b89e;\r\n  box-shadow: 0 3px 0 0 var(--island-line-soft);\r\n  transform: none;\r\n  cursor: default;\r\n}\r\n\r\n.call-btn:focus-visible { outline: 3px solid var(--island-focus); outline-offset: 3px; }\r\n\r\n.call-btn svg { width: 20px; height: 20px; flex: 0 0 20px; }\r\n\r\n.park-hint {\r\n  margin: 8px 0 0;\r\n  text-align: center;\r\n  color: var(--island-text-on-bg);\r\n  font-size: 12.5px;\r\n  line-height: 1.65;\r\n}\r\n\r\n.park-foot {\r\n  margin-top: 4px;\r\n  text-align: center;\r\n  color: var(--island-text-on-bg);\r\n  font-size: 11.5px;\r\n  line-height: 1.75;\r\n  opacity: .82;\r\n}\r\n\r\n/* 失效 / 空状态 */\r\n.park-body .state {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 12px;\r\n  padding: 64px 16px;\r\n  text-align: center;\r\n}\r\n\r\n.park-body .state-icon {\r\n  width: 62px;\r\n  height: 62px;\r\n  border: 2px solid var(--island-line);\r\n  border-radius: 50%;\r\n  display: grid;\r\n  place-items: center;\r\n  background: var(--island-content);\r\n  color: #9f927d;\r\n}\r\n\r\n.park-body .state h2 {\r\n  margin: 4px 0 0;\r\n  font-size: 18px;\r\n  font-weight: 800;\r\n  color: var(--island-ink-on-bg);\r\n}\r\n\r\n.park-body .state p {\r\n  margin: 0;\r\n  color: var(--island-text-on-bg);\r\n  font-size: 13.5px;\r\n  line-height: 1.75;\r\n  max-width: 262px;\r\n}\r\n\r\n/* Toast：暖色小卡片，和页面同一套材质 */\r\n.toast {\r\n  position: fixed;\r\n  left: 50%;\r\n  bottom: calc(96px + var(--safe-b));\r\n  transform: translate(-50%, 12px);\r\n  max-width: 84vw;\r\n  padding: 11px 18px;\r\n  border-radius: 50px;\r\n  background: rgba(24, 26, 32, .92);\r\n  color: #fff;\r\n  font-size: 13.5px;\r\n  line-height: 1.4;\r\n  opacity: 0;\r\n  pointer-events: none;\r\n  transition: opacity .2s, transform .2s;\r\n  z-index: 50;\r\n}\r\n\r\n.toast.show { opacity: 1; transform: translate(-50%, 0); }\r\n\r\n/* 扫码页的 toast 抬高到海浪页脚之上 */\r\n.park-body .toast { bottom: calc(124px + var(--safe-b)); }\r\n\r\n@media (max-width: 560px) {\r\n  .park-body .toast { bottom: calc(106px + var(--safe-b)); }\r\n}\r\n\r\n.park-body .toast {\r\n  background: var(--island-content);\r\n  border: 2px solid var(--island-line);\r\n  color: var(--island-ink);\r\n  font-weight: 600;\r\n  box-shadow: 0 8px 24px rgba(61, 52, 40, .16);\r\n}\r\n\r\n/* 拨号确认弹层 */\r\n.park-body .modal { background: rgba(61, 52, 40, .36); }\r\n\r\n.park-body .modal-card {\r\n  background: var(--island-content);\r\n  border: 2px solid var(--island-line);\r\n  border-radius: 24px;\r\n  color: var(--island-text);\r\n  font-family: inherit;\r\n  box-shadow: 0 8px 24px rgba(61, 52, 40, .18);\r\n}\r\n\r\n.park-body .cfm-title {\r\n  margin: 4px 0 8px;\r\n  font-size: 18px;\r\n  font-weight: 800;\r\n  color: var(--island-ink);\r\n}\r\n\r\n.park-body .cfm-sub { margin: 0 0 6px; color: var(--island-muted); font-size: 13.5px; }\r\n\r\n.park-body .cfm-phone {\r\n  margin: 0 0 20px;\r\n  font-size: 24px;\r\n  font-weight: 800;\r\n  letter-spacing: .06em;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--island-ink);\r\n}\r\n\r\n.park-body .cfm-actions { display: flex; gap: 10px; }\r\n\r\n.park-body .cfm-actions .btn {\r\n  flex: 1;\r\n  height: 48px;\r\n  border: 0;\r\n  border-radius: 50px;\r\n  font-size: 15px;\r\n  font-weight: 700;\r\n  color: #fff;\r\n}\r\n\r\n.park-body .cfm-cancel {\r\n  background: var(--island-input);\r\n  color: var(--island-text);\r\n  border: 2px solid var(--island-line);\r\n  box-shadow: 0 3px 0 0 var(--island-line-soft);\r\n}\r\n\r\n.park-body .cfm-cancel:active { transform: translateY(2px); box-shadow: 0 1px 0 0 var(--island-line-soft); }\r\n\r\n.park-body .cfm-ok { background: var(--island-primary); box-shadow: 0 4px 0 0 var(--island-shadow); }\r\n\r\n.park-body .cfm-ok:hover { background: var(--island-primary-hover); }\r\n\r\n.park-body .cfm-ok:active {\r\n  background: var(--island-primary-active);\r\n  transform: translateY(2px);\r\n  box-shadow: 0 1px 0 0 var(--island-shadow);\r\n}\r\n\r\n/* ============================ 后台 ============================ */\r\n\r\n.admin-body {\r\n  min-height: 100%;\r\n  background: var(--bg);\r\n}\r\n\r\n.auth {\r\n  min-height: 100vh;\r\n  display: grid;\r\n  place-items: center;\r\n  padding: 24px 18px;\r\n}\r\n\r\n.auth-card {\r\n  width: 100%;\r\n  max-width: 380px;\r\n  padding: 30px 26px 26px;\r\n  border-radius: 20px;\r\n  background: var(--surface);\r\n  box-shadow: var(--shadow);\r\n}\r\n\r\n.auth-logo {\r\n  width: 46px;\r\n  height: 46px;\r\n  border-radius: 13px;\r\n  display: grid;\r\n  place-items: center;\r\n  background: var(--brand);\r\n  color: #fff;\r\n  font-size: 20px;\r\n  font-weight: 800;\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.auth-card h1 { margin: 0 0 6px; font-size: 20px; letter-spacing: -.01em; }\r\n.auth-card .sub { margin: 0 0 22px; color: var(--ink-2); font-size: 13.5px; line-height: 1.6; }\r\n\r\n.field { margin-bottom: 14px; }\r\n.field label {\r\n  display: block;\r\n  margin-bottom: 7px;\r\n  font-size: 13px;\r\n  font-weight: 600;\r\n  color: var(--ink-2);\r\n}\r\n\r\n.input {\r\n  width: 100%;\r\n  height: 46px;\r\n  padding: 0 14px;\r\n  border: 1.5px solid var(--line);\r\n  border-radius: 11px;\r\n  background: var(--surface);\r\n  color: var(--ink);\r\n  font-size: 15px;\r\n  outline: none;\r\n  transition: border-color .15s, box-shadow .15s;\r\n}\r\n\r\ntextarea.input { height: auto; padding: 12px 14px; line-height: 1.6; resize: vertical; }\n\n/* 下拉框沿用输入框外观，右侧留出原生箭头的空间 */\nselect.input {\n  padding-right: 36px;\n  appearance: none;\n  -webkit-appearance: none;\n  background-image: linear-gradient(45deg, transparent 50%, var(--ink-3) 50%),\n    linear-gradient(135deg, var(--ink-3) 50%, transparent 50%);\n  background-position: calc(100% - 20px) 20px, calc(100% - 14px) 20px;\n  background-size: 6px 6px, 6px 6px;\n  background-repeat: no-repeat;\n  cursor: pointer;\n}\r\n\r\n.input:focus {\r\n  border-color: var(--brand);\r\n  box-shadow: 0 0 0 3px rgba(22, 119, 255, .14);\r\n}\r\n\r\n.btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 7px;\r\n  height: 46px;\r\n  padding: 0 20px;\r\n  border: 0;\r\n  border-radius: 11px;\r\n  background: var(--brand);\r\n  color: #fff;\r\n  font-size: 15px;\r\n  font-weight: 600;\r\n  white-space: nowrap;\r\n  cursor: pointer;\r\n  transition: background .15s, transform .12s, opacity .15s;\r\n}\r\n\r\n.btn svg { width: 16px; height: 16px; flex: 0 0 16px; }\r\n\r\n.btn:active { transform: scale(.985); }\r\n.btn[disabled] { opacity: .55; cursor: default; }\r\n.btn-block { width: 100%; }\r\n.btn-ghost { background: transparent; color: var(--ink-2); border: 1.5px solid var(--line); }\r\n.btn-ghost:hover { color: var(--ink); }\r\n.btn-danger { background: var(--danger); }\r\n.btn-sm { height: 36px; padding: 0 14px; font-size: 13px; border-radius: 9px; }\r\n\r\n.alert {\r\n  margin-bottom: 14px;\r\n  padding: 10px 13px;\r\n  border-radius: 10px;\r\n  background: rgba(217, 45, 32, .1);\r\n  color: var(--danger);\r\n  font-size: 13px;\r\n  line-height: 1.5;\r\n}\r\n\r\n.alert[hidden] { display: none; }\r\n\r\n/* 后台外壳 */\r\n.shell { max-width: 1080px; margin: 0 auto; padding: 22px 18px 90px; }\r\n\r\n.topbar {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 12px;\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }\r\n.brand-mark {\r\n  width: 34px; height: 34px; border-radius: 10px;\r\n  background: var(--brand); color: #fff;\r\n  display: grid; place-items: center; font-weight: 800; font-size: 15px;\r\n  flex: 0 0 34px;\r\n}\r\n.brand h1 { margin: 0; font-size: 16px; font-weight: 700; }\r\n.brand p { margin: 2px 0 0; font-size: 12px; color: var(--ink-3); }\r\n\r\n.tabs {\r\n  display: flex;\r\n  gap: 4px;\r\n  padding: 4px;\r\n  margin-bottom: 18px;\r\n  border-radius: 12px;\r\n  background: var(--surface);\r\n  box-shadow: var(--shadow);\r\n  overflow-x: auto;\r\n  scrollbar-width: none;\r\n}\r\n.tabs::-webkit-scrollbar { display: none; }\r\n\r\n.tab {\r\n  flex: 1 0 auto;\r\n  height: 38px;\r\n  padding: 0 16px;\r\n  border: 0;\r\n  border-radius: 9px;\r\n  background: transparent;\r\n  color: var(--ink-2);\r\n  font-size: 13.5px;\r\n  font-weight: 600;\r\n  white-space: nowrap;\r\n  cursor: pointer;\r\n}\r\n\r\n.tab[aria-selected=\"true\"] { background: var(--brand); color: #fff; }\r\n\r\n.panel { display: none; }\r\n.panel.active { display: block; animation: fade .18s ease; }\r\n\r\n@keyframes fade { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }\r\n\r\n.card {\r\n  padding: 18px;\r\n  border-radius: var(--radius);\r\n  background: var(--surface);\r\n  box-shadow: var(--shadow);\r\n  margin-bottom: 14px;\r\n}\r\n\r\n.card-head {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 12px;\r\n  margin-bottom: 14px;\r\n}\r\n\r\n.card-head h2 { margin: 0; font-size: 15px; font-weight: 700; }\r\n.card-head .desc { margin: 3px 0 0; font-size: 12.5px; color: var(--ink-3); }\r\n\r\n.muted { color: var(--ink-3); font-size: 12.5px; line-height: 1.6; }\r\n\r\n/* 车辆列表 */\r\n#carList { position: relative; }\r\n\r\n.car-row {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  padding: 14px 0;\r\n  border-bottom: 1px solid var(--line);\r\n  transition: background .15s;\r\n}\r\n.car-row:last-child { border-bottom: 0; padding-bottom: 0; }\r\n\r\n.car-row.is-draggable {\r\n  cursor: grab;\r\n  /* 整行可按住拖动：触摸手势交给 JS，避免按住就滚动页面 */\r\n  touch-action: pan-y;\r\n  -webkit-touch-callout: none;\r\n}\r\n.car-row.is-draggable:active { cursor: grabbing; }\r\n.car-row.is-draggable .icon-btn,\r\n.car-row.is-draggable .switch,\r\n.car-row.is-draggable .phone-chip { cursor: pointer; touch-action: manipulation; }\r\n/* 整行不参与文本选中：按住拖动不会刷出蓝色选区或复制菜单 */\r\n.car-row.is-draggable .car-row-main,\r\n.car-row.is-draggable .car-row-plate { user-select: none; -webkit-user-select: none; }\r\n\r\n/* 按住瞬间：虚化 + 轻微缩放，给出「已抓取」的即时反馈 */\r\n.car-row.is-pressed {\r\n  opacity: .55;\r\n  transform: scale(.98);\r\n  transition: opacity .12s, transform .12s;\r\n}\r\n\r\n/* 拖动中：原行让位隐藏，位置由虚线占位框表示 */\r\n.car-row.is-source { display: none; }\r\n\r\n/* 跟手的浮动卡片 */\r\n.drag-ghost {\r\n  position: fixed;\r\n  top: 0;\r\n  left: 0;\r\n  z-index: 999;\r\n  margin: 0;\r\n  padding-left: 0;\r\n  padding-right: 0;\r\n  border-radius: 10px;\r\n  background: var(--surface);\r\n  box-shadow: 0 12px 32px rgba(16, 24, 40, .22), 0 2px 6px rgba(16, 24, 40, .12);\r\n  pointer-events: none;\r\n  opacity: .96;\r\n  will-change: transform;\r\n}\r\n\r\n.drag-ghost .car-row-ops { opacity: .5; }\r\n\r\n/* 落点占位：虚线框 */\r\n.drag-placeholder {\r\n  margin: 4px 0;\r\n  border: 2px dashed var(--brand);\r\n  border-radius: 10px;\r\n  background: rgba(22, 119, 255, .06);\r\n  transition: height .12s;\r\n}\r\n\r\n/* 拖拽期间禁用文本选中，避免桌面端拖出蓝色选区 */\r\nbody.is-sorting {\r\n  user-select: none;\r\n  -webkit-user-select: none;\r\n  cursor: grabbing;\r\n}\r\nbody.is-sorting .car-row { touch-action: none; }\r\nbody.is-sorting .drag-handle { cursor: grabbing; }\r\n/* 真正拖起来之后才锁滚动，避免按下瞬间滚动条消失导致页面跳动 */\r\nbody.is-dragging-page { overflow: hidden; }\r\n\r\n.drag-handle {\r\n  flex: 0 0 32px;\r\n  width: 32px;\r\n  height: 40px;\r\n  margin-left: -8px;\r\n  display: grid;\r\n  place-items: center;\r\n  color: var(--ink-3);\r\n  cursor: grab;\r\n  /* 让浏览器把触摸手势完全交给 JS，否则一拖就被当成滚动 */\r\n  touch-action: none;\r\n  /* 桌面端拖动时不选中文字，触屏长按不弹复制菜单 */\r\n  user-select: none;\r\n  -webkit-user-select: none;\r\n  -webkit-touch-callout: none;\r\n}\r\n\r\n.drag-handle svg { width: 16px; height: 16px; pointer-events: none; }\r\n.drag-handle:active { color: var(--brand); }\r\n\r\n.car-row-main { flex: 1; min-width: 0; }\r\n.car-row-plate {\r\n  font-size: 15.5px;\r\n  font-weight: 700;\r\n  letter-spacing: .05em;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n}\r\n.car-row-sub {\r\n  margin-top: 4px;\r\n  font-size: 12.5px;\r\n  color: var(--ink-3);\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: center;\r\n  gap: 6px;\r\n}\r\n\r\n.primary-phone {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  padding: 1px 7px;\r\n  border-radius: 5px;\r\n  background: rgba(22, 163, 74, .12);\r\n  color: var(--call-strong);\r\n  font-weight: 600;\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n@media (prefers-color-scheme: dark) {\r\n  .primary-phone { color: #4ade80; background: rgba(34, 197, 94, .16); }\r\n}\r\n\r\n.phone-chips { display: inline-flex; flex-wrap: wrap; gap: 5px; }\r\n\r\n.phone-chip {\r\n  padding: 1px 7px;\r\n  border: 1px solid var(--line);\r\n  border-radius: 5px;\r\n  background: transparent;\r\n  color: var(--ink-3);\r\n  font-size: 12px;\r\n  font-variant-numeric: tabular-nums;\r\n  cursor: pointer;\r\n  transition: color .15s, border-color .15s;\r\n}\r\n\r\n.phone-chip:hover { color: var(--brand); border-color: var(--brand); }\r\n.phone-chip[disabled] { opacity: .5; cursor: default; }\r\n\r\n.tag-off {\r\n  margin-left: 8px;\r\n  padding: 1px 6px;\r\n  border-radius: 5px;\r\n  background: var(--line);\r\n  color: var(--ink-3);\r\n  font-size: 11px;\r\n  font-weight: 500;\r\n  letter-spacing: 0;\r\n}\r\n\r\n.car-row-ops { display: flex; gap: 6px; flex: 0 0 auto; }\r\n\r\n.icon-btn {\r\n  width: 34px; height: 34px;\r\n  display: grid; place-items: center;\r\n  border: 1.5px solid var(--line);\r\n  border-radius: 9px;\r\n  background: transparent;\r\n  color: var(--ink-2);\r\n  cursor: pointer;\r\n}\r\n.icon-btn:hover { color: var(--ink); border-color: var(--ink-3); }\r\n.icon-btn.danger:hover { color: var(--danger); border-color: var(--danger); }\r\n.icon-btn svg { width: 16px; height: 16px; }\r\n\r\n.empty {\r\n  padding: 34px 10px;\r\n  text-align: center;\r\n  color: var(--ink-3);\r\n  font-size: 13.5px;\r\n  line-height: 1.7;\r\n}\r\n\r\n/* 二维码区 */\r\n.qr-wrap {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 22px;\r\n  align-items: center;\r\n}\r\n\r\n.qr-canvas {\r\n  width: 200px;\r\n  height: 200px;\r\n  flex: 0 0 200px;\r\n  border-radius: 50%;\r\n  background: #fff;\r\n  padding: 0;\r\n  box-shadow: 0 0 0 1px var(--line), var(--shadow);\r\n  overflow: hidden;\r\n}\r\n\r\n.qr-canvas svg { display: block; width: 100%; height: 100%; }\r\n\r\n.qr-side { flex: 1 1 220px; min-width: 0; }\r\n.qr-link {\r\n  display: block;\r\n  padding: 10px 12px;\r\n  margin: 10px 0 14px;\r\n  border-radius: 9px;\r\n  background: var(--bg);\r\n  color: var(--ink-2);\r\n  font-size: 12.5px;\r\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\r\n  word-break: break-all;\r\n  line-height: 1.5;\r\n}\r\n\r\n.btn-row { display: flex; flex-wrap: wrap; gap: 8px; }\r\n\r\n/* 弹层 */\r\n.modal {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 100;\r\n  display: grid;\r\n  place-items: center;\r\n  padding: 18px;\r\n  background: rgba(12, 16, 22, .5);\r\n  backdrop-filter: blur(3px);\r\n}\r\n\r\n.modal[hidden] { display: none; }\r\n\r\n.modal-card {\r\n  width: 100%;\r\n  max-width: 460px;\r\n  max-height: 88vh;\r\n  overflow-y: auto;\r\n  padding: 20px;\r\n  border-radius: 18px;\r\n  background: var(--surface);\r\n  box-shadow: 0 24px 60px rgba(0, 0, 0, .3);\r\n  animation: pop .18s ease;\r\n}\r\n\r\n@keyframes pop { from { opacity: 0; transform: translateY(10px) scale(.98); } to { opacity: 1; transform: none; } }\r\n\r\n.modal-head {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  margin-bottom: 16px;\r\n}\r\n.modal-head h2 { margin: 0; font-size: 16px; }\r\n\r\n.row-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\r\n\r\n/* 弹层里的号码行：输入框 + 呼叫标记 + 删除 */\r\n.phone-row {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  margin-bottom: 8px;\r\n}\r\n\r\n.phone-row .input { flex: 1; min-width: 0; }\r\n\r\n.phone-pin {\r\n  flex: 0 0 auto;\r\n  height: 46px;\r\n  padding: 0 12px;\r\n  border: 1.5px solid var(--line);\r\n  border-radius: 10px;\r\n  background: transparent;\r\n  color: var(--ink-3);\r\n  font-size: 12.5px;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: color .15s, border-color .15s, background .15s;\r\n}\r\n\r\n.phone-pin.active {\r\n  border-color: var(--call);\r\n  background: rgba(22, 163, 74, .12);\r\n  color: var(--call-strong);\r\n}\r\n\r\n@media (prefers-color-scheme: dark) {\r\n  .phone-pin.active { color: #4ade80; }\r\n}\r\n\r\n.phone-row .icon-btn { flex: 0 0 34px; height: 46px; border-radius: 10px; }\r\n\r\n.switch { position: relative; width: 44px; height: 26px; flex: 0 0 44px; }\r\n.switch input { position: absolute; opacity: 0; width: 100%; height: 100%; margin: 0; cursor: pointer; }\r\n.switch span {\r\n  position: absolute; inset: 0; border-radius: 999px; background: var(--line);\r\n  transition: background .18s; pointer-events: none;\r\n}\r\n.switch span::after {\r\n  content: \"\"; position: absolute; top: 3px; left: 3px;\r\n  width: 20px; height: 20px; border-radius: 50%; background: #fff;\r\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .2); transition: transform .18s;\r\n}\r\n.switch input:checked + span { background: var(--call); }\r\n.switch input:checked + span::after { transform: translateX(18px); }\r\n.switch input:disabled + span { opacity: .55; }\r\n.switch input:focus-visible + span { box-shadow: 0 0 0 3px rgba(22, 119, 255, .3); }\r\n\r\n.modal-foot {\r\n  display: flex;\r\n  justify-content: flex-end;\r\n  gap: 8px;\r\n  margin-top: 20px;\r\n}\r\n\r\n/* 打印卡片 */\r\n.print-sheet { display: none; }\r\n\r\n@media print {\r\n  body { background: #fff; }\r\n  .shell, .toast, .modal { display: none !important; }\r\n  .print-sheet {\r\n    display: flex !important;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: 14px;\r\n    width: 105mm;\r\n    height: 148mm;\r\n    margin: 0 auto;\r\n    padding: 12mm;\r\n    border: 1px dashed #ccc;\r\n    text-align: center;\r\n  }\r\n  .print-sheet .p-qr { width: 72mm; height: 72mm; }\r\n  .print-sheet .p-qr svg { width: 100%; height: 100%; }\r\n  .print-sheet .p-plate {\r\n    padding: 2mm 6mm;\r\n    border: 1px solid #bbb;\r\n    border-radius: 2mm;\r\n    font-size: 16pt;\r\n    font-weight: 700;\r\n    letter-spacing: .1em;\r\n    color: #222;\r\n  }\r\n  .print-sheet .p-plate[hidden] { display: none; }\r\n  .print-sheet .p-tip { font-size: 11pt; color: #444; line-height: 1.6; }\r\n}\r\n\r\n@media (max-width: 560px) {\r\n  .shell { padding: 16px 14px 80px; }\r\n  .qr-wrap { justify-content: center; }\r\n  .qr-canvas { width: 180px; height: 180px; flex-basis: 180px; }\r\n  .row-2 { grid-template-columns: 1fr; }\r\n  .tabs { position: sticky; top: 0; z-index: 10; }\r\n}\r\n";
